import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  sourceApiAssociationConfigSchema,
  type SourceApiAssociationConfig,
} from "./source-api-association-config.js";
import {
  sourceApiAssociationStatusSchema,
  type SourceApiAssociationStatus,
} from "./source-api-association-status.js";

export type SourceApiAssociation = {
  /** The ID generated by the AppSync service for the source API association. */
  associationId?: string;
  /** The Amazon Resource Name (ARN) of the source API association. */
  associationArn?: string;
  /** The ID of the AppSync source API. */
  sourceApiId?: string;
  /** The Amazon Resource Name (ARN) of the AppSync source API. */
  sourceApiArn?: string;
  /** The Amazon Resource Name (ARN) of the AppSync Merged API. */
  mergedApiArn?: string;
  /** The ID of the AppSync Merged API. */
  mergedApiId?: string;
  /** The description field. */
  description?: string;
  sourceApiAssociationConfig?: SourceApiAssociationConfig;
  /** The state of the source API association. */
  sourceApiAssociationStatus?: SourceApiAssociationStatus;
  /** The detailed message related to the current state of the source API association. */
  sourceApiAssociationStatusDetail?: string;
  /**
   * The datetime value of the last successful merge of the source API association. The result will
   * be in UTC format and your local time zone.
   */
  lastSuccessfulMergeDate?: Date;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const sourceApiAssociationSchema: Schema<SourceApiAssociation> = s.object<SourceApiAssociation>(
  {
    associationId: s.optional(s.string()),
    associationArn: s.optional(s.string()),
    sourceApiId: s.optional(s.string()),
    sourceApiArn: s.optional(s.string()),
    mergedApiArn: s.optional(s.string()),
    mergedApiId: s.optional(s.string()),
    description: s.optional(s.string()),
    sourceApiAssociationConfig: s.optional(s.lazy(() => sourceApiAssociationConfigSchema)),
    sourceApiAssociationStatus: s.optional(s.lazy(() => sourceApiAssociationStatusSchema)),
    sourceApiAssociationStatusDetail: s.optional(s.string()),
    lastSuccessfulMergeDate: s.optional(s.dateTime()),
  },
  { additionalProperties: s.json() },
);
